const item = $input.first()?.json || {};
const outreachId = String(item.outreach_id || '').trim();

if (!outreachId) {
  throw new Error('outreach_id is required. An approved send cannot target an anonymous recipient.');
}

// Fail-closed default: dry_run is always true unless explicitly authorized as false
const dryRun = item.dry_run !== undefined ? Boolean(item.dry_run) : true;
const confirmation = String(item.confirmation || '').trim();
const expectedFingerprint = String(item.expected_fingerprint || '').trim();
const actor = String(item.actor || 'operator-n8n').trim();
const note = String(item.note || 'Approved send executed via n8n Workflow 05').trim();

return [{
  json: {
    outreach_id: outreachId,
    dry_run: dryRun,
    confirmation: confirmation,
    expected_fingerprint: expectedFingerprint,
    actor: actor,
    note: note
  }
}];

const res = $input.first()?.json || {};
const sendState = res.send_state || res.error_code || 'UNKNOWN';
const outreachId = res.outreach_id || $('Validate Preconditions & Fail-Closed Gate').first()?.json?.outreach_id || 'unknown';
const dryRun = Boolean(res.dry_run);
const retryAllowed = Boolean(res.retry_allowed);
const code = res.code || res.error_code || null;
const nextAction = res.next_action || 'Inspect outbox report.';

const isSuccess = sendState === 'SENT' || (dryRun && (sendState === 'READY_TO_SEND' || sendState === 'WOULD_SEND'));

let summary = '📤 OUTBOUND SEND REPORT\n';
summary += '• Outreach ID: ' + outreachId + '\n';
summary += '• Send State: ' + sendState + '\n';
summary += '• Dry Run: ' + dryRun + '\n';
if (code) summary += '• Code: ' + code + '\n';
summary += '• Retry Allowed: ' + retryAllowed + '\n';
summary += '• Next Action: ' + nextAction;

return [{
  json: {
    success: isSuccess,
    outreach_id: outreachId,
    send_state: sendState,
    dry_run: dryRun,
    code: code,
    retry_allowed: retryAllowed,
    summary: summary
  }
}];
